const (
	defaultPageLimit = 20
	maxPageLimit     = 100
)

// invoicePage is one page of invoices. NextCursor is empty on the last page.
type invoicePage struct {
	Items      []invoiceView `json:"items"`
	NextCursor string        `json:"next_cursor,omitempty"`
}

func (s *Server) listInvoices(w http.ResponseWriter, r *http.Request, acct store.Account) {
	q := r.URL.Query()
	limit, ok := parseLimit(q)
	if !ok {
		writeError(w, http.StatusBadRequest, "invalid_limit")
		return
	}
	var after *store.InvoicePosition
	if q.Has("cursor") {
		pos, ok := decodeCursor(q.Get("cursor"))
		if !ok {
			writeError(w, http.StatusBadRequest, "invalid_cursor")
			return
		}
		after = &pos
	}
	// One extra invoice tells whether there is another page.
	invs := s.store.InvoicePage(acct.ID, after, limit+1)
	page := invoicePage{Items: []invoiceView{}}
	if len(invs) > limit {
		invs = invs[:limit]
		last := invs[len(invs)-1]
		page.NextCursor = encodeCursor(store.InvoicePosition{CreatedAt: last.CreatedAt, ID: last.ID})
	}
	for _, inv := range invs {
		page.Items = append(page.Items, view(inv))
	}
	writeJSON(w, http.StatusOK, page)
}

// parseLimit reads the limit parameter: a whole number from 1 to maxPageLimit, or defaultPageLimit when absent.
func parseLimit(q url.Values) (int, bool) {
	if !q.Has("limit") {
		return defaultPageLimit, true
	}
	raw := q.Get("limit")
	if raw == "" {
		return 0, false
	}
	for _, c := range raw {
		if c < '0' || c > '9' {
			return 0, false
		}
	}
	n, err := strconv.Atoi(raw)
	if err != nil || n < 1 || n > maxPageLimit {
		return 0, false
	}
	return n, true
}

// cursorData is the content of a cursor before it is encoded.
type cursorData struct {
	CreatedAt time.Time `json:"created_at"`
	ID        string    `json:"id"`
}

// encodeCursor returns the opaque cursor for a position in the invoice list.
func encodeCursor(p store.InvoicePosition) string {
	// Marshaling a time and a string cannot fail.
	b, _ := json.Marshal(cursorData{CreatedAt: p.CreatedAt, ID: p.ID})
	return base64.RawURLEncoding.EncodeToString(b)
}

// decodeCursor reads a cursor from encodeCursor. It reports false for anything else.
func decodeCursor(s string) (store.InvoicePosition, bool) {
	b, err := base64.RawURLEncoding.DecodeString(s)
	if err != nil {
		return store.InvoicePosition{}, false
	}
	var c cursorData
	if err := json.Unmarshal(b, &c); err != nil || c.ID == "" || c.CreatedAt.IsZero() {
		return store.InvoicePosition{}, false
	}
	return store.InvoicePosition{CreatedAt: c.CreatedAt, ID: c.ID}, true
}

