// createInvoices adds n invoices for a customer through the API and returns their IDs, oldest first.
func createInvoices(t *testing.T, srv http.Handler, key, customerID string, n int) []string {
	t.Helper()
	ids := []string{}
	body := `{"customer_id":"` + customerID + `","lines":[{"description":"Seats","quantity":1,"unit_cents":100}]}`
	for i := 0; i < n; i++ {
		r := do(t, srv, "POST", "/api/invoices", key, body)
		if r.Code != http.StatusCreated {
			t.Fatalf("create invoice: %d %s", r.Code, r.Body)
		}
		var v struct {
			ID string `json:"id"`
		}
		if err := json.Unmarshal(r.Body.Bytes(), &v); err != nil {
			t.Fatal(err)
		}
		ids = append(ids, v.ID)
	}
	return ids
}

// invoicePage fetches one page of invoices. It returns the IDs on the page and the next cursor.
func invoicePage(t *testing.T, srv http.Handler, key, query string) ([]string, string) {
	t.Helper()
	r := do(t, srv, "GET", "/api/invoices?"+query, key, "")
	if r.Code != http.StatusOK {
		t.Fatalf("list %q: %d %s", query, r.Code, r.Body)
	}
	var body struct {
		Items []struct {
			ID string `json:"id"`
		} `json:"items"`
		NextCursor string `json:"next_cursor"`
	}
	if err := json.Unmarshal(r.Body.Bytes(), &body); err != nil {
		t.Fatal(err)
	}
	ids := []string{}
	for _, it := range body.Items {
		ids = append(ids, it.ID)
	}
	return ids, body.NextCursor
}

// walkInvoices follows next cursors from the first page until the last one and returns every ID seen.
func walkInvoices(t *testing.T, srv http.Handler, key, limit string) []string {
	t.Helper()
	all := []string{}
	query := "limit=" + limit
	for pages := 0; ; pages++ {
		if pages > 1000 {
			t.Fatal("paging does not end")
		}
		ids, next := invoicePage(t, srv, key, query)
		all = append(all, ids...)
		if next == "" {
			return all
		}
		query = "limit=" + limit + "&cursor=" + next
	}
}

// errorCode returns the error code of an error response.
func errorCode(t *testing.T, r *httptest.ResponseRecorder) string {
	t.Helper()
	var body map[string]string
	if err := json.Unmarshal(r.Body.Bytes(), &body); err != nil {
		t.Fatalf("error body %s: %v", r.Body, err)
	}
	return body["error"]
}

func TestInvoicesAreAPageAtATimeWithTheDefaultLimit(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	ids := createInvoices(t, srv, "key-acme", c.ID, 25)

	first, next := invoicePage(t, srv, "key-acme", "")
	if len(first) != 20 || next == "" {
		t.Fatalf("first page: %d items, next %q", len(first), next)
	}
	second, next := invoicePage(t, srv, "key-acme", "cursor="+next)
	if len(second) != 5 || next != "" {
		t.Fatalf("last page: %d items, next %q", len(second), next)
	}
	if got := append(first, second...); !slices.Equal(got, ids) {
		t.Fatalf("pages %v, want %v", got, ids)
	}
}

func TestAPageOfExactlyTheLimitHasNoNextCursor(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	ids := createInvoices(t, srv, "key-acme", c.ID, 20)
	if got, next := invoicePage(t, srv, "key-acme", ""); !slices.Equal(got, ids) || next != "" {
		t.Fatalf("got %v next %q, want all 20 and no next cursor", got, next)
	}
}

func TestWalkingThePagesReturnsEveryInvoiceOnceInCreationOrder(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	ids := createInvoices(t, srv, "key-acme", c.ID, 23)
	for _, limit := range []string{"1", "7", "23", "100"} {
		if got := walkInvoices(t, srv, "key-acme", limit); !slices.Equal(got, ids) {
			t.Fatalf("limit %s: %v, want %v", limit, got, ids)
		}
	}
}

func TestAnEmptyAccountHasAnEmptyPage(t *testing.T) {
	srv, _ := newServer(t)
	r := do(t, srv, "GET", "/api/invoices", "key-globex", "")
	if r.Code != http.StatusOK || !strings.Contains(r.Body.String(), `"items":[]`) || strings.Contains(r.Body.String(), "next_cursor") {
		t.Fatalf("empty list: %d %s", r.Code, r.Body)
	}
}

func TestTheLimitMustBeAWholeNumberFromOneToOneHundred(t *testing.T) {
	srv, _ := newServer(t)
	for _, limit := range []string{"0", "101", "-1", "abc", "1.5", "", "+5", "99999999999999999999"} {
		r := do(t, srv, "GET", "/api/invoices?limit="+limit, "key-acme", "")
		if r.Code != http.StatusBadRequest || errorCode(t, r) != "invalid_limit" {
			t.Fatalf("limit %q: %d %s", limit, r.Code, r.Body)
		}
	}
	for _, limit := range []string{"1", "100"} {
		if r := do(t, srv, "GET", "/api/invoices?limit="+limit, "key-acme", ""); r.Code != http.StatusOK {
			t.Fatalf("limit %q: %d %s", limit, r.Code, r.Body)
		}
	}
}

func TestAnUnreadableCursorIsInvalid(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	createInvoices(t, srv, "key-acme", c.ID, 3)
	noTime := base64.RawURLEncoding.EncodeToString([]byte(`{"id":"inv_00001"}`))
	noID := base64.RawURLEncoding.EncodeToString([]byte(`{"created_at":"2026-01-02T03:04:05Z"}`))
	for _, cursor := range []string{"garbage!", "", "not-base64==", noTime, noID, base64.RawURLEncoding.EncodeToString([]byte("[]"))} {
		r := do(t, srv, "GET", "/api/invoices?cursor="+cursor, "key-acme", "")
		if r.Code != http.StatusBadRequest || errorCode(t, r) != "invalid_cursor" {
			t.Fatalf("cursor %q: %d %s", cursor, r.Code, r.Body)
		}
