package api_test

import (
	"encoding/base64"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"testing"
	"time"

	"example.com/saasapi/internal/api"
	"example.com/saasapi/internal/store"
)

func newServer(t *testing.T) (*api.Server, *store.Store) {
	t.Helper()
	st := store.New()
	st.AddAccount(store.Account{ID: "acc_acme", Name: "Acme", Plan: store.PlanFree, TaxRateBP: 825})
	st.AddAccount(store.Account{ID: "acc_globex", Name: "Globex", Plan: store.PlanPro})
	st.AddKey("key-acme", "acc_acme")
	st.AddKey("key-globex", "acc_globex")
	now := time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)
	return api.New(st, api.Options{Now: func() time.Time { return now }}), st
}

func do(t *testing.T, h http.Handler, method, path, key, body string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(method, path, strings.NewReader(body))
	if key != "" {
		req.Header.Set("X-API-Key", key)
	}
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec
}

func TestARequestWithoutAValidKeyIsUnauthorized(t *testing.T) {
	srv, _ := newServer(t)
	for _, key := range []string{"", "nope"} {
		if r := do(t, srv, "GET", "/api/customers", key, ""); r.Code != http.StatusUnauthorized {
			t.Fatalf("key %q: status %d", key, r.Code)
		}
	}
	if r := do(t, srv, "GET", "/healthz", "", ""); r.Code != http.StatusOK {
		t.Fatalf("healthz: %d", r.Code)
	}
}

func TestCreateAndReadACustomer(t *testing.T) {
	srv, _ := newServer(t)
	r := do(t, srv, "POST", "/api/customers", "key-acme", `{"name":"Jane Doe","email":"jane@example.com","plan":"pro"}`)
	if r.Code != http.StatusCreated {
		t.Fatalf("create: %d %s", r.Code, r.Body)
	}
	var c store.Customer
	if err := json.Unmarshal(r.Body.Bytes(), &c); err != nil || c.ID == "" || c.Plan != store.PlanPro {
		t.Fatalf("created %+v %v", c, err)
	}
	if r := do(t, srv, "GET", "/api/customers/"+c.ID, "key-acme", ""); r.Code != http.StatusOK {
		t.Fatalf("get: %d", r.Code)
	}
	if r := do(t, srv, "POST", "/api/customers", "key-acme", `{"name":"","email":"x"}`); r.Code != http.StatusUnprocessableEntity {
		t.Fatalf("invalid customer: %d", r.Code)
	}
}

func TestAnotherAccountsCustomerIsNotFound(t *testing.T) {
	srv, st := newServer(t)
	c, err := st.CreateCustomer("acc_globex", "Hank", "hank@globex.test", store.PlanFree, time.Now())
	if err != nil {
		t.Fatal(err)
	}
	if r := do(t, srv, "GET", "/api/customers/"+c.ID, "key-acme", ""); r.Code != http.StatusNotFound {
		t.Fatalf("cross-account read: %d", r.Code)
	}
	r := do(t, srv, "GET", "/api/customers", "key-acme", "")
	if strings.Contains(r.Body.String(), c.ID) {
		t.Fatalf("another account's customer is listed: %s", r.Body)
	}
}

func TestAnInvoiceHasItsTotals(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	r := do(t, srv, "POST", "/api/invoices", "key-acme", `{"customer_id":"`+c.ID+`","lines":[{"description":"Pro plan","quantity":1,"unit_cents":10000}]}`)
	if r.Code != http.StatusCreated {
		t.Fatalf("create invoice: %d %s", r.Code, r.Body)
	}
	var v struct {
		ID     string `json:"id"`
		Totals struct {
			TotalCents int64 `json:"total_cents"`
		} `json:"totals"`
	}
	if err := json.Unmarshal(r.Body.Bytes(), &v); err != nil || v.Totals.TotalCents != 10825 {
		t.Fatalf("invoice %s %v", r.Body, err)
	}
	if r := do(t, srv, "GET", "/api/invoices/"+v.ID, "key-globex", ""); r.Code != http.StatusNotFound {
		t.Fatalf("cross-account invoice: %d", r.Code)
	}
}

// createInvoices adds n invoices for a customer through the API and returns their IDs, oldest first.
func createInvoices(t *testing.T, srv http.Handler, key, customerID string, n int) []string {
	t.Helper()
	ids := []string{}
	body := `{"customer_id":"` + customerID + `","lines":[{"description":"Seats","quantity":1,"unit_cents":100}]}`
	for i := 0; i < n; i++ {
		r := do(t, srv, "POST", "/api/invoices", key, body)
		if r.Code != http.StatusCreated {
			t.Fatalf("create invoice: %d %s", r.Code, r.Body)
		}
		var v struct {
			ID string `json:"id"`
		}
		if err := json.Unmarshal(r.Body.Bytes(), &v); err != nil {
			t.Fatal(err)
		}
		ids = append(ids, v.ID)
	}
	return ids
}

// invoicePage fetches one page of invoices. It returns the IDs on the page and the next cursor.
func invoicePage(t *testing.T, srv http.Handler, key, query string) ([]string, string) {
	t.Helper()
	r := do(t, srv, "GET", "/api/invoices?"+query, key, "")
	if r.Code != http.StatusOK {
		t.Fatalf("list %q: %d %s", query, r.Code, r.Body)
	}
	var body struct {
		Items []struct {
			ID string `json:"id"`
		} `json:"items"`
		NextCursor string `json:"next_cursor"`
	}
	if err := json.Unmarshal(r.Body.Bytes(), &body); err != nil {
		t.Fatal(err)
	}
	ids := []string{}
	for _, it := range body.Items {
		ids = append(ids, it.ID)
	}
	return ids, body.NextCursor
}

// walkInvoices follows next cursors from the first page until the last one and returns every ID seen.
func walkInvoices(t *testing.T, srv http.Handler, key, limit string) []string {
	t.Helper()
	all := []string{}
	query := "limit=" + limit
	for pages := 0; ; pages++ {
		if pages > 1000 {
			t.Fatal("paging does not end")
		}
		ids, next := invoicePage(t, srv, key, query)
		all = append(all, ids...)
		if next == "" {
			return all
		}
		query = "limit=" + limit + "&cursor=" + next
	}
}

// errorCode returns the error code of an error response.
func errorCode(t *testing.T, r *httptest.ResponseRecorder) string {
	t.Helper()
	var body map[string]string
	if err := json.Unmarshal(r.Body.Bytes(), &body); err != nil {
		t.Fatalf("error body %s: %v", r.Body, err)
	}
	return body["error"]
}

func TestInvoicesAreAPageAtATimeWithTheDefaultLimit(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	ids := createInvoices(t, srv, "key-acme", c.ID, 25)

	first, next := invoicePage(t, srv, "key-acme", "")
	if len(first) != 20 || next == "" {
		t.Fatalf("first page: %d items, next %q", len(first), next)
	}
	second, next := invoicePage(t, srv, "key-acme", "cursor="+next)
	if len(second) != 5 || next != "" {
		t.Fatalf("last page: %d items, next %q", len(second), next)
	}
	if got := append(first, second...); !slices.Equal(got, ids) {
		t.Fatalf("pages %v, want %v", got, ids)
	}
}

func TestAPageOfExactlyTheLimitHasNoNextCursor(t *testing.T) {
