func TestTheLimitMustBeAWholeNumberFromOneToOneHundred(t *testing.T) {
	srv, _ := newServer(t)
	for _, limit := range []string{"0", "101", "-1", "abc", "1.5", "", "+5", "99999999999999999999"} {
		r := do(t, srv, "GET", "/api/invoices?limit="+limit, "key-acme", "")
		if r.Code != http.StatusBadRequest || errorCode(t, r) != "invalid_limit" {
			t.Fatalf("limit %q: %d %s", limit, r.Code, r.Body)
		}
	}
	for _, limit := range []string{"1", "100"} {
		if r := do(t, srv, "GET", "/api/invoices?limit="+limit, "key-acme", ""); r.Code != http.StatusOK {
			t.Fatalf("limit %q: %d %s", limit, r.Code, r.Body)
		}
	}
}

func TestAnUnreadableCursorIsInvalid(t *testing.T) {
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	createInvoices(t, srv, "key-acme", c.ID, 3)
	noTime := base64.RawURLEncoding.EncodeToString([]byte(`{"id":"inv_00001"}`))
	noID := base64.RawURLEncoding.EncodeToString([]byte(`{"created_at":"2026-01-02T03:04:05Z"}`))
	for _, cursor := range []string{"garbage!", "", "not-base64==", noTime, noID, base64.RawURLEncoding.EncodeToString([]byte("[]"))} {
		r := do(t, srv, "GET", "/api/invoices?cursor="+cursor, "key-acme", "")
		if r.Code != http.StatusBadRequest || errorCode(t, r) != "invalid_cursor" {
			t.Fatalf("cursor %q: %d %s", cursor, r.Code, r.Body)
		}
	}
}

func TestPagingDoesNotSkipOrRepeatWhenInvoicesAreCreatedBetweenPages(t *testing.T) {
	st := store.New()
	st.AddAccount(store.Account{ID: "acc_acme", Name: "Acme", Plan: store.PlanFree, TaxRateBP: 825})
	st.AddKey("key-acme", "acc_acme")
	// Each invoice gets a later time than the one before it.
	clock := time.Date(2026, 1, 2, 3, 4, 5, 0, time.UTC)
	srv := api.New(st, api.Options{Now: func() time.Time { clock = clock.Add(time.Second); return clock }})
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())

	seen := []string{}
	ids := createInvoices(t, srv, "key-acme", c.ID, 5)
	page, next := invoicePage(t, srv, "key-acme", "limit=2")
	seen = append(seen, page...)

	// New invoices arrive while the client is partway through.
	ids = append(ids, createInvoices(t, srv, "key-acme", c.ID, 2)...)
	page, next = invoicePage(t, srv, "key-acme", "limit=2&cursor="+next)
	seen = append(seen, page...)

	ids = append(ids, createInvoices(t, srv, "key-acme", c.ID, 1)...)
	for next != "" {
		page, next = invoicePage(t, srv, "key-acme", "limit=2&cursor="+next)
		seen = append(seen, page...)
	}
	if !slices.Equal(seen, ids) {
		t.Fatalf("paged %v, want %v", seen, ids)
	}
}

func TestAnInvoiceCreatedAtTheSameTimeSortsByID(t *testing.T) {
	// A fixed clock gives every invoice the same creation time, so the order comes from the ID alone.
	srv, st := newServer(t)
	c, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	ids := createInvoices(t, srv, "key-acme", c.ID, 12)
	if got := walkInvoices(t, srv, "key-acme", "5"); !slices.Equal(got, ids) {
		t.Fatalf("paged %v, want %v", got, ids)
	}
}

func TestAPageNeverShowsAnotherAccountsInvoices(t *testing.T) {
	srv, st := newServer(t)
	acme, _ := st.CreateCustomer("acc_acme", "Jane", "jane@example.com", store.PlanPro, time.Now())
	globex, _ := st.CreateCustomer("acc_globex", "Hank", "hank@globex.test", store.PlanPro, time.Now())
	acmeIDs := createInvoices(t, srv, "key-acme", acme.ID, 3)
	globexIDs := createInvoices(t, srv, "key-globex", globex.ID, 3)

	if got := walkInvoices(t, srv, "key-globex", "2"); !slices.Equal(got, globexIDs) {
		t.Fatalf("globex pages %v, want %v", got, globexIDs)
	}
	// A cursor from one account used with another account's key shows only the other account's invoices.
	_, next := invoicePage(t, srv, "key-acme", "limit=1")
	got, _ := invoicePage(t, srv, "key-globex", "cursor="+next)
	for _, id := range got {
		if slices.Contains(acmeIDs, id) {
			t.Fatalf("another account's invoice %s is listed: %v", id, got)
		}
	}
}

